package com.msb.ecom.inventory_service.operations;import lombok.RequiredArgsConstructor;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import java.time.Clock;import java.util.List;
@Service @RequiredArgsConstructor
public class InventoryOperationsService {private final InventoryOperationsRepository repository;private final Clock clock=Clock.systemUTC();@Value("${inventory.reservations.expiry-enabled:true}")private boolean expiryEnabled;
 public InventoryOperationsContracts.Snapshot snapshot(){return new InventoryOperationsContracts.Snapshot("INVENTORY",true,"Inventory operational signals loaded.",List.of(),repository.outbox(),List.of(),repository.issues(clock.instant()),null,List.of(new InventoryOperationsContracts.Feature("INVENTORY_RESERVATION_EXPIRY","Inventory reservation expiry",expiryEnabled?"ENABLED":"DISABLED","SERVICE","Inventory runtime configuration",null,false,"Releases expired active reservations through the existing scheduled worker."),new InventoryOperationsContracts.Feature("INVENTORY_OUTBOX_RETRY","Inventory outbox retry","UNAVAILABLE","SERVICE","Inventory domain capability",null,false,"Inventory outbox visibility is read-only until a bounded publisher/retry mechanism exists.")));}
 public InventoryOperationsContracts.Action action(InventoryOperationsContracts.ActionRequest r){if(r==null)throw new IllegalArgumentException("Action is required.");return new InventoryOperationsContracts.Action("INVENTORY",r.targetType(),r.targetId(),r.commandType(),"READ_ONLY",false,"SYSTEM_OPERATION_NOT_SUPPORTED",List.of("Inventory expiry worker"),List.of("The existing cleanup worker is batch-driven; ADM-SYS does not add an arbitrary release command."),"No operation will run.","Inventory quantities and reservation state remain unchanged.",r.dryRun()?null:"NOT_RETRYABLE","Inventory operational issues are read-only in this milestone.");}
}
